        'publish',
        'binaries',
        'web-spa',
        'release-provenance',
        'install-pin-bump',
        'installer-smoke',
        'watchdog',
        'binaries-pr',
        'binaries-smoke-gate',
        'ci-red-report',
      ];
      for (final id in untouched) {
        final job = jobs[id] as YamlMap;
        expect(
