import yaml
doc = yaml.safe_load(open('.github/workflows/ci.yml'))
jobs = doc['jobs']
# compute quality-gate closure
closure = set()
def collect(n):
    if n in closure: return
    closure.add(n)
    needs = jobs.get(n, {}).get('needs')
    if isinstance(needs, str): collect(needs)
    elif isinstance(needs, list):
        for x in needs: collect(x)
collect('quality-gate')
guarded = closure | {'step-timings', 'release', 'js-ext-integration'}
for name in sorted(guarded):
    j = jobs.get(name)
    if j is None:
        print(name, 'MISSING'); continue
    print(f"{name}\n  needs={j.get('needs')}\n  if={j.get('if')}\n")
EOF"}

